Number = Union[int, float]

class Money:
    """A monetary amount in a single currency.

    Examples:
        >>> Money(5, "USD") + Money(7, "USD")
        Money(12, 'USD')
        >>> Money(5, "USD") + Money(7, "EUR")
        Traceback (most recent call last):
        ValueError: currency mismatch
    """
    def __init__(self, amount: Number, currency: str) -> None:
        if amount is None or currency is None:
            raise TypeError("amount and currency must be provided")
        self.amount: Number = amount
        self.currency: str = currency

    def __add__(self, other: Any) -> "Money":
        if not isinstance(other, Money):
            return NotImplemented
        if self.currency != other.currency:
            raise ValueError("currency mismatch")
        return Money(self.amount + other.amount, self.currency)

    def __repr__(self) -> str:
        return f"Money({self.amount}, '{self.currency}')"

