class Queue:
    """A simple first-in/first-out queue.

    Examples:
        >>> q = Queue()
        >>> q.enqueue("a")
        >>> q.enqueue("b")
        >>> q.size
        2
        >>> q.dequeue()
        'a'
        >>> q.dequeue()
        'b'
        >>> q.dequeue()
        Traceback (most recent call last):
        IndexError: dequeue from empty queue
    """
    def __init__(self) -> None:
        self._items: List[Any] = []

    def enqueue(self, item: Any) -> None:
        self._items.append(item)

    def dequeue(self) -> Any:
        if not self._items:
            raise IndexError("dequeue from empty queue")
        return self._items.pop(0)

    @property
    def size(self) -> int:
        return len(self._items)

    @property
    def is_empty(self) -> bool:
        return not self._items

from typing import Any, Dict


def coerce_int(value: Any) -> int:
    if isinstance(value, bool):
        raise TypeError("cannot coerce bool to int")
    if isinstance(value, int):
        return value
    if isinstance(value, str):
        candidate = value.strip()
        if not candidate.lstrip("-+").isdigit():
            raise ValueError(f"cannot coerce {value!r} to int")
        return int(candidate)
    raise TypeError(f"cannot coerce {type(value).__name__} to int")


def coerce_and_validate(data: Any, schema: Dict[str, type]) -> Dict[str, int]:
    """Coerce and validate a dict against a {key: type} schema.

    Args:
        data: The candidate dict.
        schema: Mapping from key to expected Python type.

    Returns:
        A new dict with all values coerced to int (only int schema supported here).

    Raises:
        TypeError: If data is not a dict or any value cannot be coerced.
        ValueError: If a key is missing.

    Examples:
        >>> coerce_and_validate({"a": "3", "b": 2}, {"a": int, "b": int})
        {'a': 3, 'b': 2}
        >>> coerce_and_validate({"a": "x"}, {"a": int})
        Traceback (most recent call last):
        ...
        ValueError: cannot coerce 'x' to int
    """
    if not isinstance(data, dict):
        raise TypeError(f"data must be a dict, got {type(data).__name__}")
    result: Dict[str, int] = {}
    for key, expected in schema.items():
        if key not in data:
            raise ValueError(f"missing key: {key!r}")
        if not isinstance(data[key], expected):
            try:
                result[key] = coerce_int(data[key])
            except (TypeError, ValueError) as exc:
                raise ValueError(f"key {key!r}: {exc}") from exc
        else:
            result[key] = data[key]
    return result

from typing import Dict, Iterable

class ScoreTracker:
    """Count events by name and answer 'in' lookups against history.

    Examples:
        >>> t = ScoreTracker()
        >>> t.record("login")
        >>> t.record("logout")
        >>> t.record("login")
        >>> "login" in t
        True
        >>> "missing" in t
        False
        >>> t["login"]
        2
    """
    def __init__(self) -> None:
        self._counts: Dict[str, int] = {}

    def record(self, event: str) -> None:
        if not isinstance(event, str) or not event:
            raise ValueError("event must be a non-empty string")
        self._counts[event] = self._counts.get(event, 0) + 1

    def __contains__(self, event: str) -> bool:
        return event in self._counts

    def __getitem__(self, event: str) -> int:
        return self._counts.get(event, 0)

