from typing import Optional

def valid_parens(s: str) -> bool:
    """Check whether s is a valid parenthesis sequence.

    Args:
        s: A string of '(' and ')'.

    Returns:
        True if the parentheses are balanced, False otherwise.

    Examples:
        >>> valid_parens("()()")
        True
        >>> valid_parens("())")
        False
        >>> valid_parens("")
        True
    """
    return _match(s, 0)

def _match(s: str, i: int) -> bool:
    if i == len(s):
        return True
    if s[i] == ")":
        return False
    return _find_close(s, i + 1, 1)

def _find_close(s: str, i: int, depth: int) -> bool:
    if i >= len(s):
        return False
    if s[i] == "(":
        return _find_close(s, i + 1, depth + 1)
    depth -= 1
    if depth == 0:
        return i + 1 == len(s) or _match(s, i + 1)
    return _find_close(s, i + 1, depth)

