class StringBuilder:
    """A growing string buffer with += support.

    Examples:
        >>> sb = StringBuilder()
        >>> sb += "hello"
        >>> sb += " "
        >>> sb += "world"
        >>> str(sb)
        'hello world'
        >>> len(sb)
        11
    """
    def __init__(self) -> None:
        self._parts: List[str] = []

    def __iadd__(self, piece: str) -> "StringBuilder":
        if piece is None:
            return self
        self._parts.append(piece)
        return self

    def __str__(self) -> str:
        return "".join(self._parts)

    def __len__(self) -> int:
        return sum(len(p) for p in self._parts)

from typing import Any, Callable

class LazyProperty:
    """Descriptor that computes and caches on first read.

    Examples:
        >>> s = Settings()
        >>> s.calls
        0
        >>> s.heavy
        42
        >>> s.heavy
        42
        >>> s.calls
        1
    """
    def __init__(self, func: Callable[[Any], Any]) -> None:
        self.func: Callable[[Any], Any] = func
        self.attr_name: str = func.__name__

    def __get__(self, instance: Any, owner: type) -> Any:
        if instance is None:
            return self
        if not hasattr(instance, "_lazy"):
            instance._lazy = {}
        cache = instance._lazy
        if self.attr_name not in cache:
            cache[self.attr_name] = self.func(instance)
        return cache[self.attr_name]

class Settings:
    """An example class showing LazyProperty."""
    calls: int = 0

    @LazyProperty
    def heavy(self) -> int:
        Settings.calls += 1
        return 42

from typing import Iterator, List

def miller_rabin(n: int, bases: List[int]) -> bool:
    """Return True if n passes Miller-Rabin for every base."""
    if n < 2:
        return False
    for p in (2, 3, 5, 7, 11, 13):
        if n % p == 0:
            return n == p
    d = n - 1
    r = 0
    while d % 2 == 0:
        d //= 2
        r += 1
    for a in bases:
        a %= n
        if a == 0:
            continue
        x = mod_pow(a, d, n)
        if x == 1 or x == n - 1:
            continue
        for _ in range(r - 1):
            x = mod_pow(x, 2, n)
            if x == n - 1:
                break
        else:
            return False
    return True

def filter_probable_primes(nums: Iterator[int]) -> Iterator[int]:
    """Yield nums that pass Miller-Rabin with the fixed bases."""
    bases = [2, 3, 5, 7, 11]
    for n in nums:
        if miller_rabin(n, bases):
            yield n

from typing import Any, List

class StackEmptyError(Exception):
    """Raised when an operation requires a non-empty stack."""
    pass

class Stack:
    """A simple LIFO stack implemented on top of a Python list.

    Examples:
        >>> s = Stack()
        >>> s.push(1)
        >>> s.push(2)
        >>> s.pop()
        2
        >>> s.peek()
        1
        >>> s.is_empty()
        False
    """
    def __init__(self) -> None:
        self._data: List[Any] = []

    def push(self, item: Any) -> None:
        self._data.append(item)

    def pop(self) -> Any:
        if not self._data:
            raise StackEmptyError("pop from empty stack")
        return self._data.pop()

    def peek(self) -> Any:
        if not self._data:
            raise StackEmptyError("peek from empty stack")
        return self._data[-1]

    def is_empty(self) -> bool:
        return not self._data

    def size(self) -> int:
        return len(self._data)

import re
from typing import Any, Dict, List, Optional


def _check_type(value: Any, expected: str) -> None:
    mapping = {
        "string": str,
        "integer": int,
        "number": (int, float),
        "boolean": bool,
        "array": list,
        "object": dict,
    }
    py_type = mapping.get(expected)
    if py_type is None:
        raise ValueError(f"unknown schema type: {expected}")
    if expected == "integer" and isinstance(value, bool):
        raise ValueError(f"expected integer, got boolean")
    if not isinstance(value, py_type):
        raise ValueError(f"expected {expected}, got {type(value).__name__}")


def validate_schema_simple(value: Any, schema: Dict[str, Any]) -> None:
    """Validate value against a tiny subset of JSON Schema.

    Args:
        value: The candidate value.
        schema: Schema with optional 'type', 'minLength', 'pattern', 'enum'.

    Raises:
        TypeError: If schema is not a dict.
        ValueError: If value violates the schema.

    Examples:
        >>> validate_schema_simple("abc", {"type": "string", "minLength": 2})
        >>> validate_schema_simple("a", {"type": "string", "minLength": 2})
        Traceback (most recent call last):
        ...
        ValueError: string length 1 below minLength 2
    """
    if not isinstance(schema, dict):
        raise TypeError("schema must be a dict")
    if "type" in schema:
        _check_type(value, schema["type"])
    if "minLength" in schema:
        if not isinstance(value, str):
            raise ValueError("minLength only applies to strings")
        if len(value) < schema["minLength"]:
            raise ValueError(f"string length {len(value)} below minLength {schema['minLength']}")
    if "pattern" in schema:
        if not isinstance(value, str):
            raise ValueError("pattern only applies to strings")
        if not re.search(schema["pattern"], value):
            raise ValueError(f"value {value!r} does not match pattern {schema['pattern']!r}")
    if "enum" in schema:
        enum: List[Any] = list(schema["enum"])
        if value not in enum:
            raise ValueError(f"value {value!r} not in enum {enum}")

from typing import List

Matrix = List[List[float]]

def determinant(matrix: Matrix) -> float:
    """Compute the determinant of a square matrix.

    Args:
        matrix: An n x n list of lists.

    Returns:
        The determinant as a float.

    Raises:
        ValueError: If matrix is not square.

    Examples:
        >>> determinant([[1, 2], [3, 4]])
        -2.0
        >>> determinant([[5]])
        5.0
    """
    n = len(matrix)
    if n == 0:
        return 1.0
    if any(len(row) != n for row in matrix):
        raise ValueError("matrix must be square")
    if n == 1:
        return float(matrix[0][0])
    if n == 2:
        return float(matrix[0][0] * matrix[1][1] - matrix[0][1] * matrix[1][0])
    total = 0.0
    for j in range(n):
        sub = [row[:j] + row[j + 1:] for row in matrix[1:]]
        total += ((-1) ** j) * matrix[0][j] * determinant(sub)
    return float(total)

import functools
from typing import Callable

@functools.lru_cache(maxsize=None)
def fib_cached(n: int) -> int:
    """Return the n-th Fibonacci number with memoization.

    Args:
        n: Non-negative integer.

    Returns:
        The n-th Fibonacci number.

    Examples:
        >>> fib_cached(10)
        55
        >>> fib_cached(20)
        6765
    """
    if n < 0:
        raise ValueError("n must be non-negative")
    if n < 2:
        return n
    return fib_cached(n - 1) + fib_cached(n - 2)

def clear_fib_cache(func: Callable[..., int] = fib_cached) -> None:
    """Clear the lru_cache of fib_cached."""
    func.cache_clear()

from typing import Dict, Optional

def char_frequency(text: Optional[str]) -> Dict[str, int]:
    """Return a dict mapping each character to its frequency in text.

    Args:
        text: The input string.

    Returns:
        A dict of counts.

    Examples:
        >>> sorted(char_frequency("hello").items())
        [('e', 1), ('h', 1), ('l', 2), ('o', 1)]
        >>> char_frequency("")
        {}
        >>> char_frequency(None)
        {}
    """
    if not text:
        return {}
    freq: Dict[str, int] = {}
    for ch in text:
        freq[ch] = freq.get(ch, 0) + 1
    return freq

from typing import Any, Callable, Dict, Type, get_type_hints
from functools import wraps

def enforce_types(type_map: Dict[str, Type[Any]]) -> Callable[[Callable[..., Any]], Callable[..., Any]]:
    """Build a decorator that enforces argument types for a function.

    Args:
        type_map: Mapping from argument name to expected type.

    Returns:
        A decorator that wraps the function and rejects mismatched arguments.

    Examples:
        >>> @enforce_types({"x": int, "y": int})
        ... def add(x, y):
        ...     return x + y
        >>> add(1, 2)
        3
        >>> add(1, "2")
        Traceback (most recent call last):
        ...
        TypeError: argument 'y' must be int, got str
    """
    def decorator(func: Callable[..., Any]) -> Callable[..., Any]:
        @wraps(func)
        def wrapper(*args: Any, **kwargs: Any) -> Any:
            hints = get_type_hints(func)
            for arg_name, expected in type_map.items():
                if arg_name in kwargs:
                    value = kwargs[arg_name]
                else:
                    try:
                        value = _bind_arg(func, arg_name, args)
                    except IndexError:
                        continue
                if not isinstance(value, expected):
                    raise TypeError(
                        f"argument {arg_name!r} must be {expected.__name__}, "
                        f"got {type(value).__name__}"
                    )
            return func(*args, **kwargs)
        return wrapper
    return decorator

def _bind_arg(func: Callable[..., Any], name: str, args: tuple) -> Any:
    import inspect
    sig = inspect.signature(func)
    params = [p for p in sig.parameters.values() if p.kind in (p.POSITIONAL_OR_KEYWORD, p.POSITIONAL_ONLY)]
    for i, p in enumerate(params):
        if p.name == name:
            return args[i]
    raise IndexError(name)

