class Counter:
    """A counter that supports in-place addition.

    Examples:
        >>> c = Counter(10)
        >>> c += 5
        >>> c.value
        15
        >>> (Counter(0) + 7).value
        7
    """
    def __init__(self, value: Number = 0) -> None:
        self.value: Number = value

    def __iadd__(self, other: Number) -> "Counter":
        if other is None:
            return self
        self.value += other
        return self

    def __add__(self, other: Number) -> "Counter":
        if other is None:
            raise TypeError("cannot add None")
        return Counter(self.value + other)

    def __repr__(self) -> str:
        return f"Counter({self.value})"

