import functools
from pathlib import Path
from typing import Callable, Any

def rotate_output(max_bytes: int = 10 * 1024 * 1024, backups: int = 3) -> Callable[..., Any]:
    """Decorator that rotates the output file when it grows beyond 'max_bytes'.

    Args:
        max_bytes: Threshold for rotation in bytes.
        backups: Number of previous versions to retain on disk.

    Returns:
        A decorator that wraps a function with rotation behavior.

    Examples:
        >>> @rotate_output(max_bytes=10, backups=1)
        ... def append_line(p, t): Path(p).write_text(t)
        >>> callable(append_line)
        True
    """
    if max_bytes <= 0:
        raise ValueError("max_bytes must be > 0")
    if backups < 0:
        raise ValueError("backups must be >= 0")

    def decorator(func: Callable[..., Any]) -> Callable[..., Any]:
        @functools.wraps(func)
        def wrapper(path: Any, *args: Any, **kwargs: Any) -> Any:
            p = Path(path)
            if p.exists() and p.stat().st_size > max_bytes:
                for i in range(backups, 0, -1):
                    older = p.with_suffix(p.suffix + f".{i}")
                    newer = p.with_suffix(p.suffix + f".{i - 1}")
                    if older.exists():
                        older.unlink()
                    if newer.exists():
                        newer.rename(older)
                if p.exists():
                    p.rename(p.with_suffix(p.suffix + ".0"))
            return func(path, *args, **kwargs)
        return wrapper
    return decorator

