from typing import List, Optional

Board = List[List[int]]

def solve_sudoku(board: Board) -> Optional[Board]:
    """Solve a 9x9 sudoku board in-place using backtracking.

    Args:
        board: A 9x9 grid of integers where 0 denotes an empty cell.

    Returns:
        The solved board, or None if no solution exists.

    Examples:
        >>> b = [
        ...     [5, 3, 0, 0, 7, 0, 0, 0, 0],
        ...     [6, 0, 0, 1, 9, 5, 0, 0, 0],
        ...     [0, 9, 8, 0, 0, 0, 0, 6, 0],
        ... ]
        >>> solve_sudoku(b) is not None
        True
    """
    empty = _find_empty(board)
    if empty is None:
        return board
    row, col = empty
    for num in range(1, 10):
        if _is_safe(board, row, col, num):
            board[row][col] = num
            if solve_sudoku(board) is not None:
                return board
            board[row][col] = 0
    return None

def _find_empty(board: Board) -> Optional[tuple]:
    for r in range(9):
        for c in range(9):
            if board[r][c] == 0:
                return (r, c)
    return None

def _is_safe(board: Board, row: int, col: int, num: int) -> bool:
    if num in board[row]:
        return False
    for r in range(9):
        if board[r][col] == num:
            return False
    box_r, box_c = 3 * (row // 3), 3 * (col // 3)
    for r in range(box_r, box_r + 3):
        for c in range(box_c, box_c + 3):
            if board[r][c] == num:
                return False
    return True

from typing import Callable, Any, Dict, Tuple
from functools import wraps

def memoize(func: Callable[..., Any]) -> Callable[..., Any]:
    """Memoize a function using a recursive descent into tuple arguments.

    Args:
        func: A pure function whose arguments are hashable (or tuples of hashables).

    Returns:
        A wrapped function with a shared cache.

    Examples:
        >>> @memoize
        ... def add(x: int, y: int) -> int:
        ...     return x + y
        >>> add(2, 3)
        5
        >>> add(2, 3)
        5
    """
    cache: Dict[Tuple[Any, ...], Any] = {}
    @wraps(func)
    def wrapper(*args: Any) -> Any:
        key = _to_key(args)
        if key not in cache:
            cache[key] = func(*args)
        return cache[key]
    wrapper.cache_clear = lambda: cache.clear()
    return wrapper

def _to_key(args: Tuple[Any, ...]) -> Tuple[Any, ...]:
    out = []
    for a in args:
        if isinstance(a, list):
            out.append(_to_key(tuple(a)))
        elif isinstance(a, dict):
            out.append(tuple(sorted((k, _to_key(v)) for k, v in a.items())))
        else:
            out.append(a)
    return tuple(out)

from abc import ABC, abstractmethod
from typing import Any, List


class Predicate(ABC):
    """Abstract base for composable predicates."""

    @abstractmethod
    def check(self, value: Any) -> bool:
        """Return True if the value passes."""

    def __call__(self, value: Any) -> bool:
        return self.check(value)

    def __and__(self, other: "Predicate") -> "Predicate":
        return all_of(self, other)

    def __or__(self, other: "Predicate") -> "Predicate":
        return any_of(self, other)

    def __invert__(self) -> "Predicate":
        return none_of(self)


class _IsInstance(Predicate):
    def __init__(self, *types: type):
        if not types:
            raise ValueError("at least one type required")
        self._types = types
    def check(self, value: Any) -> bool:
        if bool in self._types and isinstance(value, bool):
            return False
        return isinstance(value, self._types)


class _AllOf(Predicate):
    def __init__(self, *predicates: Predicate):
        if not predicates:
            raise ValueError("all_of needs at least one predicate")
        self._preds: List[Predicate] = list(predicates)
    def check(self, value: Any) -> bool:
        return all(p.check(value) for p in self._preds)


class _AnyOf(Predicate):
    def __init__(self, *predicates: Predicate):
        if not predicates:
            raise ValueError("any_of needs at least one predicate")
        self._preds: List[Predicate] = list(predicates)
    def check(self, value: Any) -> bool:
        return any(p.check(value) for p in self._preds)


class _NoneOf(Predicate):
    def __init__(self, *predicates: Predicate):
        if not predicates:
            raise ValueError("none_of needs at least one predicate")
        self._preds: List[Predicate] = list(predicates)
    def check(self, value: Any) -> bool:
        return not any(p.check(value) for p in self._preds)


def is_instance(*types: type) -> Predicate:
    """Predicate that succeeds when value is an instance of one of types."""
    return _IsInstance(*types)


def all_of(*predicates: Predicate) -> Predicate:
    """Logical AND over predicates."""
    return _AllOf(*predicates)


def any_of(*predicates: Predicate) -> Predicate:
    """Logical OR over predicates."""
    return _AnyOf(*predicates)


def none_of(*predicates: Predicate) -> Predicate:
    """Logical NOR over predicates."""
    return _NoneOf(*predicates)


