def retry_with_fallback(max_attempts: int = 3,
                         exceptions: Tuple[Type[BaseException], ...] = (Exception,),
                         fallback: Optional[Callable[[BaseException], Any]] = None) -> Callable[[Callable[..., Any]], Callable[..., Any]]:
    """Retry a function; on exhaustion, optionally call fallback(last_error).

    Args:
        max_attempts: Total attempts (>=1).
        exceptions: Exception types that trigger a retry.
        fallback: Optional callable invoked with the last exception when attempts are exhausted.

    Returns:
        A decorator.

    Examples:
        >>> @retry_with_fallback(max_attempts=2, exceptions=(ZeroDivisionError,),
        ...                      fallback=lambda e: "default")
        ... def f(): raise ZeroDivisionError("x")
        >>> f()
        'default'
    """
    if max_attempts < 1:
        raise ValueError("max_attempts must be >= 1")
    if fallback is not None and not callable(fallback):
        raise TypeError("fallback must be callable or None")
    def decorator(func: Callable[..., Any]) -> Callable[..., Any]:
        def wrapper(*args: Any, **kwargs: Any) -> Any:
            last: BaseException = RuntimeError("unreachable")
            for attempt in range(1, max_attempts + 1):
                try:
                    return func(*args, **kwargs)
                except exceptions as exc:
                    last = exc
                    if attempt == max_attempts:
                        break
            if fallback is not None:
                return fallback(last)
            raise last
        wrapper.__name__ = getattr(func, "__name__", "wrapped")
        return wrapper
    return decorator

