@dataclass(frozen=True)
class Point:
    """A 2D point validated against a configurable bound.

    Examples:
        >>> Point(1, 2, bound=10)
        Point(x=1, y=2, bound=10)
        >>> Point(20, 1, bound=10)
        Traceback (most recent call last):
        ...
        ValueError: x=20 outside [-10, 10]
    """
    x: int
    y: int
    bound: int = field(default=100)

    def __post_init__(self) -> None:
        if isinstance(self.x, bool) or not isinstance(self.x, int):
            raise TypeError(f"x must be int, got {type(self.x).__name__}")
        if isinstance(self.y, bool) or not isinstance(self.y, int):
            raise TypeError(f"y must be int, got {type(self.y).__name__}")
        if isinstance(self.bound, bool) or not isinstance(self.bound, int) or self.bound <= 0:
            raise ValueError(f"bound must be a positive int, got {self.bound!r}")
        for axis, value in (("x", self.x), ("y", self.y)):
            if not (-self.bound <= value <= self.bound):
                raise ValueError(f"{axis}={value} outside [{-self.bound}, {self.bound}]")

    def as_tuple(self) -> Tuple[int, int]:
        """Return the (x, y) coordinates."""
        return (self.x, self.y)

