from typing import List

def binary_search(values: List[int], target: int) -> int:
    """Recursively search a sorted list for a target value.

    Args:
        values: A list sorted in ascending order.
        target: The value to locate.

    Returns:
        The index of target, or -1 if not found.

    Examples:
        >>> binary_search([1, 3, 5, 7, 9], 5)
        2
        >>> binary_search([1, 3, 5, 7, 9], 4)
        -1
        >>> binary_search([], 1)
        -1
    """
    if not isinstance(values, list):
        raise TypeError("values must be a list")
    return _binary_search(values, target, 0, len(values) - 1)

def _binary_search(values: List[int], target: int, lo: int, hi: int) -> int:
    if lo > hi:
        return -1
    mid = (lo + hi) // 2
    if values[mid] == target:
        return mid
    if values[mid] < target:
        return _binary_search(values, target, mid + 1, hi)
    return _binary_search(values, target, lo, mid - 1)

