from typing import Dict, Optional

class _TrieNode:
    __slots__ = ("children", "is_word")
    def __init__(self) -> None:
        self.children: Dict[str, "_TrieNode"] = {}
        self.is_word: bool = False

class Trie:
    """A prefix tree for lowercase alphabetic words.

    Examples:
        >>> t = Trie()
        >>> t.insert("apple")
        >>> t.search("apple")
        True
        >>> t.search("app")
        False
        >>> t.starts_with("app")
        True
    """
    def __init__(self) -> None:
        self._root = _TrieNode()

    def insert(self, word: str) -> None:
        if not isinstance(word, str):
            raise TypeError("word must be a str")
        node = self._root
        for ch in word:
            node = node.children.setdefault(ch, _TrieNode())
        node.is_word = True

    def search(self, word: str) -> bool:
        node = self._find_node(word)
        return node is not None and node.is_word

    def starts_with(self, prefix: str) -> bool:
        return self._find_node(prefix) is not None

    def _find_node(self, s: str) -> Optional[_TrieNode]:
        if not isinstance(s, str):
            raise TypeError("input must be a str")
        node = self._root
        for ch in s:
            if ch not in node.children:
                return None
            node = node.children[ch]
        return node

from typing import Any, Dict, List, Union

Schema = Union[type, Dict[str, "Schema"], List["Schema"], None]

def validate(value: Any, schema: Schema) -> Any:
    """Recursively validate value against schema.

    Schema forms:
      - A Python type: value must be an instance.
      - A dict {key: subschema}: value must be a dict with all matching keys.
      - A list [subschema]: value must be a list and every item must match.
      - None: any value is accepted.

    Args:
        value: The candidate value.
        schema: The schema to validate against.

    Returns:
        The value, unchanged.

    Raises:
        ValueError: If validation fails at any level.
        TypeError: If schema is not a supported type.

    Examples:
        >>> validate({"a": [1, 2]}, {"a": [int]})
        {'a': [1, 2]}
        >>> validate({"a": [1, "x"]}, {"a": [int]})
        Traceback (most recent call last):
        ...
        ValueError: at a[1]: expected int, got str
    """
    if schema is None:
        return value
    if isinstance(schema, type):
        if isinstance(schema, bool) and not isinstance(value, bool):
            raise ValueError(f"expected {schema.__name__}, got {type(value).__name__}")
        if schema is int and isinstance(value, bool):
            raise ValueError(f"expected int, got bool")
        if not isinstance(value, schema):
            raise ValueError(f"expected {schema.__name__}, got {type(value).__name__}")
        return value
    if isinstance(schema, dict):
        if not isinstance(value, dict):
            raise ValueError(f"expected object, got {type(value).__name__}")
        for k, sub in schema.items():
            if k not in value:
                raise ValueError(f"missing key: {k!r}")
            try:
                validate(value[k], sub)
            except ValueError as exc:
                raise ValueError(f"at {k!r}: {exc}") from exc
        return value
    if isinstance(schema, list):
        if not schema:
            raise ValueError("empty list schemas are not allowed")
        if not isinstance(value, list):
            raise ValueError(f"expected array, got {type(value).__name__}")
        item_schema = schema[0]
        for i, item in enumerate(value):
            try:
                validate(item, item_schema)
            except ValueError as exc:
                raise ValueError(f"at [{i}]: {exc}") from exc
        return value
    raise TypeError(f"unsupported schema node: {schema!r}")

from typing import Callable, Dict

class Scenario:
    """A tiny decorator-driven use-case registry.

    Examples:
        >>> s = Scenario()
        >>> @s.use_case('greet')
        ... def greet():
        ...     return 'hi'
        >>> s.run_all()
        {'greet': 'hi'}
    """
    def __init__(self) -> None:
        self._cases: Dict[str, Callable[[], object]] = {}

    def use_case(self, name: str) -> Callable[[Callable[[], object]], Callable[[], object]]:
        def decorator(fn: Callable[[], object]) -> Callable[[], object]:
            if name in self._cases:
                raise ValueError(f"duplicate use case: {name!r}")
            self._cases[name] = fn
            return fn
        return decorator

    def run_all(self) -> Dict[str, object]:
        return {name: fn() for name, fn in self._cases.items()}

