from typing import Dict, Any

KV_RE = re.compile(r"""([A-Za-z_][A-Za-z0-9_]*)\s*:\s*(\d+(?:\.\d+)?|'[^']*'|"[^"]*")""")

def parse_simple_object(text: str) -> Dict[str, Any]:
    """Parse a flat JS-style object literal into a dict.

    Args:
        text: Object string like '{a:1, b:2}'.

    Returns:
        Dict of key->value (numbers become int/float, quoted become str).

    Examples:
        >>> sorted(parse_simple_object("{a:1, b:'two', c:3.5}").items())
        [('a', 1), ('b', 'two'), ('c', 3.5)]
        >>> parse_simple_object("{}")
        {}
    """
    if not isinstance(text, str):
        raise TypeError("text must be a str")
    inner = text.strip()
    if inner.startswith("{") and inner.endswith("}"):
        inner = inner[1:-1]
    out: Dict[str, Any] = {}
    for match in KV_RE.finditer(inner):
        key, raw = match.group(1), match.group(2)
        if raw.startswith("'") or raw.startswith('"'):
            out[key] = raw[1:-1]
        elif "." in raw:
            out[key] = float(raw)
        else:
            out[key] = int(raw)
    return out

from typing import Dict, Any

def flatten_dict(d: Dict[Any, Any], parent_key: str = "") -> Dict[str, Any]:
    """Flatten a nested dict into dot-separated keys.

    Args:
        d: The dictionary to flatten.
        parent_key: Accumulated key prefix (used internally).

    Returns:
        A flat dict where nested keys are joined with '.'.

    Examples:
        >>> flatten_dict({"a": {"b": 1, "c": {"d": 2}}})
        {'a.b': 1, 'a.c.d': 2}
        >>> flatten_dict({"x": 5})
        {'x': 5}
    """
    if not isinstance(d, dict):
        raise TypeError("d must be a dict")
    out: Dict[str, Any] = {}
    for k, v in d.items():
        key = f"{parent_key}.{k}" if parent_key else str(k)
        if isinstance(v, dict):
            out.update(flatten_dict(v, key))
        else:
            out[key] = v
    return out

