class CacheWithStats:
    """A dict-like cache that records hit and miss counts.

    Examples:
        >>> c = CacheWithStats()
        >>> c['x'] = 1
        >>> c.get('x')
        1
        >>> c.get('y')
        >>> c.hits
        1
        >>> c.misses
        1
        >>> c.hit_rate
        0.5
    """
    def __init__(self) -> None:
        self._data: Dict[str, Any] = {}
        self._hits: int = 0
        self._misses: int = 0

    def __setitem__(self, key: str, value: Any) -> None:
        self._data[key] = value

    def get(self, key: str, default: Any = None) -> Any:
        if key in self._data:
            self._hits += 1
            return self._data[key]
        self._misses += 1
        return default

    @property
    def hits(self) -> int:
        return self._hits

    @property
    def misses(self) -> int:
        return self._misses

    @property
    def hit_rate(self) -> float:
        total: int = self._hits + self._misses
        if total == 0:
            return 0.0
        return self._hits / total

