from pathlib import Path
from typing import Union, List

def delete_empty_dirs(root: Union[str, Path]) -> int:
    """Recursively delete empty directories under 'root'.

    Args:
        root: Root directory to scan.

    Returns:
        Number of empty directories removed.

    Examples:
        >>> delete_empty_dirs("/tmp/empty_demo_dir") >= 0
        True
    """
    base = Path(root)
    if not base.is_dir():
        return 0
    removed: List[Path] = []
    for p in sorted(base.rglob("*"), reverse=True):
        if p.is_dir():
            try:
                next(p.iterdir())
            except StopIteration:
                try:
                    p.rmdir()
                    removed.append(p)
                except OSError:
                    pass
            except OSError:
                continue
    try:
        next(base.iterdir())
    except StopIteration:
        try:
            base.rmdir()
            removed.append(base)
        except OSError:
            pass
    except OSError:
        pass
    return len(removed)

from typing import Any, Dict, List, Tuple


def _to_bool(value: Any) -> bool:
    if isinstance(value, bool):
        return value
    if isinstance(value, str):
        v = value.strip().lower()
        if v in ("true", "1", "yes", "on"):
            return True
        if v in ("false", "0", "no", "off"):
            return False
    if isinstance(value, int) and not isinstance(value, bool):
        return bool(value)
    raise ValueError(f"cannot coerce {value!r} to bool")


def _to_int(value: Any) -> int:
    if isinstance(value, bool):
        raise ValueError("cannot coerce bool to int")
    if isinstance(value, int):
        return value
    if isinstance(value, str) and value.strip().lstrip("-+").isdigit():
        return int(value.strip())
    raise ValueError(f"cannot coerce {value!r} to int")


def validate_config(data: Any) -> Tuple[Dict[str, Any], List[str]]:
    """Validate and coerce a small config dict.

    Args:
        data: Candidate dict with keys 'host', 'port', 'debug'.

    Returns:
        A tuple (clean_dict, errors). errors is empty on success.

    Examples:
        >>> validate_config({"host": "x", "port": "80", "debug": "yes"})[0]['port']
        80
        >>> validate_config({})[1]
        ['missing key: host', 'missing key: port', 'missing key: debug']
    """
    errors: List[str] = []
    result: Dict[str, Any] = {}
    if not isinstance(data, dict):
        return {}, [f"config must be a dict, got {type(data).__name__}"]
    host = data.get("host", data.get("host", "MISSING"))
    if "host" not in data:
        errors.append("missing key: host")
    elif not isinstance(data["host"], str) or not data["host"]:
        errors.append("host must be a non-empty string")
    else:
        result["host"] = data["host"]
    if "port" not in data:
        errors.append("missing key: port")
    else:
        try:
            port = _to_int(data["port"])
            if not (1 <= port <= 65535):
                raise ValueError(f"port {port} out of range")
            result["port"] = port
        except ValueError as exc:
            errors.append(f"port: {exc}")
    if "debug" not in data:
        errors.append("missing key: debug")
    else:
        try:
            result["debug"] = _to_bool(data["debug"])
        except ValueError as exc:
            errors.append(f"debug: {exc}")
    return result, errors

