from bisect import bisect_left

class SparseList:
    """A sparse list storing only the populated indices.

    Examples:
        >>> s = SparseList()
        >>> s.set(3, 'a'); s.set(7, 'b')
        >>> s.get(3)
        'a'
        >>> s.get(7)
        'b'
        >>> s.get(0) is None
        True
    """
    def __init__(self) -> None:
        self._indexes: List[int] = []
        self._values: List[Any] = []

    def set(self, index: int, value: Any) -> None:
        if index < 0:
            raise ValueError("negative index")
        pos = bisect_left(self._indexes, index)
        if pos < len(self._indexes) and self._indexes[pos] == index:
            self._values[pos] = value
        else:
            self._indexes.insert(pos, index)
            self._values.insert(pos, value)

    def get(self, index: int) -> Any:
        if index < 0:
            raise ValueError("negative index")
        pos = bisect_left(self._indexes, index)
        if pos < len(self._indexes) and self._indexes[pos] == index:
            return self._values[pos]
        return None

    def items(self) -> List[Tuple[int, Any]]:
        return list(zip(self._indexes, self._values))

