from copy import deepcopy

def deep_merge(a: Dict[Any, Any], b: Dict[Any, Any]) -> Dict[Any, Any]:
    """Recursively merge dict b into a (b wins on leaf conflicts).

    Args:
        a: Base dict; not mutated.
        b: Dict to merge on top.

    Returns:
        A new dict with nested dicts merged recursively.

    Examples:
        >>> a = {"x": {"y": 1, "z": 2}}; b = {"x": {"y": 99}, "w": 7}
        >>> deep_merge(a, b)
        {'x': {'y': 99, 'z': 2}, 'w': 7}
        >>> deep_merge({}, {})
        {}
    """
    out: Dict[Any, Any] = dict(a)
    for k, v in b.items():
        if k in out and isinstance(out[k], dict) and isinstance(v, dict):
            out[k] = deep_merge(out[k], v)
        else:
            out[k] = deepcopy(v) if isinstance(v, (dict, list)) else v
    return out

