class CountingItems:
    """A slotted frequency counter with a top-n method.

    Examples:
        >>> c = CountingItems()
        >>> for w in ['a', 'b', 'a', 'c', 'a']:
        ...     c[w] += 1
        >>> c.most_common(2)
        [('a', 3), ('b', 1)]
        >>> c.most_common(0)
        []
    """
    __slots__ = ("_counts",)

    def __init__(self) -> None:
        self._counts: Dict[Any, int] = {}

    def __setitem__(self, key: Any, value: int) -> None:
