        counter = StdCounter(self._counts)
        return counter.most_common(n)

from dataclasses import dataclass
from math import gcd
from typing import Union

Number = Union[int, "Fraction"]

@dataclass(frozen=True)
class Fraction:
    """An immutable reduced rational number.

    Examples:
        >>> Fraction(1, 2) + Fraction(1, 3)
        Fraction(5, 6)
        >>> Fraction(2, 4) == Fraction(1, 2)
        True
    """
    num: int
    den: int

    def __post_init__(self) -> None:
        if self.den == 0:
            raise ZeroDivisionError("denominator must be non-zero")
        if self.den < 0:
            object.__setattr__(self, "num", -self.num)
            object.__setattr__(self, "den", -self.den)
        g = gcd(abs(self.num), abs(self.den))
        if g:
            object.__setattr__(self, "num", self.num // g)
            object.__setattr__(self, "den", self.den // g)

    def _to_pair(other: Number) -> tuple:
        if isinstance(other, Fraction):
            return other.num, other.den
        return int(other), 1

    def __add__(self, other: Number) -> "Fraction":
        a, b = Fraction._to_pair(other)
        return Fraction(self.num * b + a * self.den, self.den * b)

    def __sub__(self, other: Number) -> "Fraction":
        a, b = Fraction._to_pair(other)
        return Fraction(self.num * b - a * self.den, self.den * b)

    def __mul__(self, other: Number) -> "Fraction":
        a, b = Fraction._to_pair(other)
        return Fraction(self.num * a, self.den * b)

    def __truediv__(self, other: Number) -> "Fraction":
        a, b = Fraction._to_pair(other)
        if a == 0:
            raise ZeroDivisionError("division by zero")
        return Fraction(self.num * b, self.den * a)

from pathlib import Path
from typing import Union, Dict, Any

def _coerce(text: str) -> Any:
    stripped = text.strip()
    if not stripped:
        return ""
    lowered = stripped.lower()
    if lowered in ("true", "false"):
        return lowered == "true"
    try:
        return int(stripped)
    except ValueError:
        pass
    try:
        return float(stripped)
    except ValueError:
        pass
    if (stripped.startswith('"') and stripped.endswith('"')) or \
       (stripped.startswith("'") and stripped.endswith("'")):
        return stripped[1:-1]
    return stripped


def read_kv_config(path: Union[str, Path], encoding: str = "utf-8") -> Dict[str, Any]:
    """Parse a key=value configuration file with comments and type coercion.

    Args:
        path: Path to the config file.
        encoding: Character encoding for the file.

    Returns:
        A dict with coerced values (int, float, bool, or stripped string).

    Examples:
        >>> read_kv_config("empty.cfg") == {}
        True
    """
    out: Dict[str, Any] = {}
    p = Path(path)
    if not p.exists():
        return out
    with p.open("r", encoding=encoding) as f:
        for lineno, raw in enumerate(f, start=1):
            line = raw.strip()
            if not line or line.startswith("#"):
                continue
            if "=" not in line:
                raise ValueError(f"line {lineno}: expected '=' separator")
            key, _, value = line.partition("=")
            key = key.strip()
            if not key:
                raise ValueError(f"line {lineno}: empty key")
            out[key] = _coerce(value)
    return out


def write_kv_config(path: Union[str, Path], data: Dict[str, Any], encoding: str = "utf-8") -> int:
    """Write a dict as key=value lines; return the number of entries written.

    Args:
        path: Destination path.
        data: Mapping of keys to values.
        encoding: Character encoding.

    Returns:
        The number of entries serialized.

    Examples:
        >>> write_kv_config("out.cfg", {}) == 0
        True
    """
    p = Path(path)
    if p.parent and not p.parent.exists():
        p.parent.mkdir(parents=True, exist_ok=True)
    with p.open("w", encoding=encoding) as f:
        for k in sorted(data):
            f.write(f"{k}={data[k]}\n")
    return len(data)

from typing import List, Optional, Dict

def min_coins(coins: List[int], amount: int) -> int:
    """Compute the minimum coins to form amount.

    Args:
        coins: A list of distinct positive coin denominations.
        amount: A non-negative target amount.

    Returns:
        The minimum number of coins needed; -1 if impossible.

    Examples:
        >>> min_coins([1, 5, 10, 25], 41)
        4
        >>> min_coins([2], 3)
        -1
    """
    if amount < 0:
        raise ValueError("amount must be non-negative")
    memo: Dict[int, int] = {0: 0}
    return _solve(coins, amount, memo)

def _solve(coins: List[int], amount: int, memo: Dict[int, int]) -> int:
    if amount in memo:
        return memo[amount]
    if amount < 0:
        return -1
    best = -1
    for c in coins:
        sub = _solve(coins, amount - c, memo)
        if sub != -1:
            candidate = 1 + sub
            if best == -1 or candidate < best:
                best = candidate
    memo[amount] = best
    return best

