def binary_search(sorted_list: List[int], target: int) -> int:
    """Find target in a sorted list using binary search.

    Args:
        sorted_list: A non-empty list sorted in ascending order.
        target: The value to find.

    Returns:
        Index of target if found, otherwise -1.

    Raises:
        ValueError: If sorted_list is empty.

    Examples:
        >>> binary_search([1, 3, 5, 7, 9], 7)
        3
        >>> binary_search([1, 3, 5, 7, 9], 4)
        -1
    """
    if not sorted_list:
        raise ValueError("sorted_list must be non-empty")
    return _search(sorted_list, target, 0, len(sorted_list) - 1)

def _search(a: List[int], target: int, lo: int, hi: int) -> int:
    if lo > hi:
        return -1
    mid = (lo + hi) // 2
    if a[mid] == target:
        return mid
    if a[mid] < target:
        return _search(a, target, mid + 1, hi)
    return _search(a, target, lo, mid - 1)

from typing import Dict

def prime_factors(n: int) -> Dict[int, int]:
    """Return the prime factorization of n.

    Args:
        n: A positive integer.

    Returns:
        A dict of {prime: exponent}. Empty when n == 1.

    Examples:
        >>> prime_factors(84)
        {2: 2, 3: 1, 7: 1}
        >>> prime_factors(1)
        {}
    """
    if n < 1:
        raise ValueError("n must be a positive integer")
    out: Dict[int, int] = {}
    d = 2
    while d * d <= n:
        while n % d == 0:
            out[d] = out.get(d, 0) + 1
            n //= d
        d += 1
    if n > 1:
        out[n] = out.get(n, 0) + 1
    return out

