def first_index_and_count(lst: List[Hashable]) -> Dict[Hashable, Tuple[int, int]]:
    """Compute (first index, total count) for each element of lst.

    Args:
        lst: A list.

    Returns:
        A dict mapping each element to (first_index, count).

    Examples:
        >>> first_index_and_count(["a", "b", "a", "c", "a", "b"])
        {'a': (0, 3), 'b': (1, 2), 'c': (3, 1)}
        >>> first_index_and_count([])
        {}
    """
    out: Dict[Hashable, Tuple[int, int]] = {}
    for i, x in enumerate(lst):
        if x in out:
            out[x] = (out[x][0], out[x][1] + 1)
        else:
            out[x] = (i, 1)
    return out

