class AddableMixin:
    """Adds support for the + operator over numeric scalars."""
    def __add__(self, other: Any) -> "Numbers":
        if not isinstance(other, (int, float)):
            return NotImplemented
        return Numbers(self.value + other)

class ComparableMixin:
    """Adds support for < comparisons between instances."""
    def __lt__(self, other: Any) -> bool:
        if not isinstance(other, ComparableMixin):
            return NotImplemented
        return self.value < other.value

class Numbers(AddableMixin, ComparableMixin):
    """A numeric wrapper composed of addable and comparable behavior.

    Examples:
        >>> a = Numbers(3)
        >>> b = Numbers(5)
        >>> a < b
        True
        >>> (a + 4).value
        7
    """
    def __init__(self, value: int) -> None:
        self.value = value

    def __repr__(self) -> str:
        return f"Numbers({self.value})"

from typing import Any, List

class QueueEmptyError(Exception):
    """Raised when dequeue is attempted on an empty queue."""
    pass

class TwoStackQueue:
    """A FIFO queue implemented with two stacks.

    Examples:
        >>> q = TwoStackQueue()
        >>> q.enqueue(1)
        >>> q.enqueue(2)
        >>> q.dequeue()
        1
        >>> q.dequeue()
        2
    """
    def __init__(self) -> None:
        self._inbox: List[Any] = []
        self._outbox: List[Any] = []

    def enqueue(self, item: Any) -> None:
        self._inbox.append(item)

    def dequeue(self) -> Any:
        if not self._outbox:
            if not self._inbox:
                raise QueueEmptyError("dequeue from empty queue")
            while self._inbox:
                self._outbox.append(self._inbox.pop())
        return self._outbox.pop()

    def is_empty(self) -> bool:
        return not self._inbox and not self._outbox

    def size(self) -> int:
        return len(self._inbox) + len(self._outbox)

from typing import List, Optional, Dict

def decode_ways(s: str) -> List[str]:
    """Decode a digit string into every possible letter sequence.

    Args:
        s: A non-empty string of digits.

    Returns:
        A list of decoded strings; each maps a partition of s into 1- or 2-digit codes.

    Raises:
        ValueError: If s contains non-digit characters.

    Examples:
        >>> sorted(decode_ways("12"))
        ['AB', 'L']
        >>> decode_ways("0")
        []
    """
    if not s:
        return []
    if any(not ch.isdigit() for ch in s):
        raise ValueError("s must contain only digits")
    memo: Dict[int, List[str]] = {}
    return _decode(s, 0, memo)

def _decode(s: str, i: int, memo: Dict[int, List[str]]) -> List[str]:
    if i in memo:
        return memo[i]
    if i == len(s):
        return [""]
    out: List[str] = []
    if s[i] != "0":
        out.extend(ch + rest for rest in _decode(s, i + 1, memo) for ch in [_letter(int(s[i]))])
    if i + 1 < len(s) and s[i] != "0" and int(s[i:i + 2]) <= 26:
        out.extend(ch + rest for rest in _decode(s, i + 2, memo) for ch in [_letter(int(s[i:i + 2]))])
    memo[i] = out
    return out

def _letter(value: int) -> str:
    return chr(ord("A") + value - 1)
